INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62192823', 62192823, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN NEGERI PULAU PUNJUNG 01', 'Langganan Internet', 'Barang', 'E-Purchasing', 'Sumatera Barat, Dharmas Raya (Kab.)', 164880000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 12, BLN, @ 13740000 )', '1. Langganan Internet ( 12, BLN, @ 13740000 );', '1. Penyedia layanan merupakan badan usaha yang sah dan terdaftar sesuai ketentuan peraturan perundang-undangan. 2. Memiliki izin penyelenggaraan jasa akses internet (ISP) yang masih berlaku dari instansi berwenang. 3. Menyediakan layanan internet dengan koneksi stabil dan berkelanjutan selama masa kontrak. 4. Kecepatan layanan internet disesuaikan dengan kebutuhan instansi, dengan jaminan Service Level Agreement (SLA). 6. Menyediakan dukungan teknis (technical support) yang dapat dihubungi pada hari dan jam kerja, serta layanan gangguan (troubleshooting). 7. Menjamin keamanan jaringan dan perlindungan data sesuai standar yang berlaku. 8. Menyediakan perangkat pendukung layanan sesuai kebutuhan (apabila diperlukan). 9. Bersedia melakukan instalasi, pemeliharaan, dan perbaikan layanan selama masa berlangganan. 10. Memiliki pengalaman dalam menyediakan layanan internet untuk instansi pemerintah/perkantoran. 11. Bersedia melengkapi dan mematuhi seluruh ketentuan administrasi serta kontrak yang ditetapkan oleh instansi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 273676);
