INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62160774', 62160774, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK', 'Pengadaan Tenaga Ahli Senior Operator Mainframe', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 244200000, 'December 2025', 'APBD', 1, 1, '2 orang x 12 bulan', 'Memenuhi kebutuhan sumber daya manusia teknis dalam mendukung keberlangsungan operasional Data Center Diskominfotik Provinsi DKI Jakarta melalui operasional sistem mainframe termasuk proses job scheduling, monitoring, troubleshooting dan backup, pemenuhan standar keamanan informasi dan kesiapan audit dalam sertifikasi ISO 27001:2022.', '1) Menjalankan dan memonitor batch job kompleks pada sistem mainframe. 2) Melakukan backup data bulanan dan tahunan menggunakan tape library serta virtual tap/disk. 3) Melakukan troubleshooting atas error job serta berkoordinasi dengan administrator terkait. 4) Menganalisis tren gangguan dan menyusun rekomendasi perbaikan sistem. 5) Membimbing dan memberikan arahan teknis kepada Junior Operator Mainframe. 6) Menyusun laporan operasional mainframe bulanan dan tahunan. 7) Melakukan optimasi penjadwalan job untuk meningkatkan efisiensi dan keandalan sistem. 8) Melakukan review dan evaluasi performa sistem mainframe secara berkala. 9) Mengikuti pelatihan internal guna meningkatkan kompetensi dan keahlian teknis. 10) Menyusun rencana peningkatan kapasitas sistem mainframe sesuai kebutuhan operasional.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 275544);
