INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62160831', 62160831, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA TALU', 'Pos Bantuan Hukum Tahun Anggaran Pengadilan Agama Talu 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Sumatera Barat, Pasaman Barat (Kab.)', 75000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '750 Orang', 'Pekerjaan ini merupakan pengadaan layanan bantuan hukum (posbakum) dengan jenis jasa hukum yang diberikan berupa pemberian informasi, advis, konsultasi dan pembuatan gugatan/permohonan, rincian sebagai berikut: 1. Pemberi layanan Konsultansi Bantuan hukum beroperasi sesuai dengan ketentuan pada hari kerja dan jam Pengadilan Agama Talu. 2. Membuat daftar petugas Posbakum Pengadilan dan sistem pengaturan rotasi para petugas Posbakum Pengadilan, serta mengajukannya ke Ketua Pengadilan Agama. 3. Membuat jadwal hari dan jam kerja layanan bantuan hukum. 4. Memberikan layanan yang profesional dan bertanggung jawab. 5. Memberikan informasi hukum dan informasi lain yang terkait secara jelas dan akurat. 6. Memberikan konsultasi atau advis hukum yang seimbang dan komprehensif. 7. Merahasiakan sesuatu yang diketahui atau diperoleh dari Penerima Layanan Posbakum Pengadilan. 8. Menjalankan prinsip-prinsip perlindungan terhadap penyandang disabilitas, perempuan, anak-anak, dan orang lanjut usia. 9. Menghindari konflik kepentingan dengan Penerima Layanan Posbakum Pengadilan. 10. Membuat laporan dan mendokumentasikan berkas 11. Dalam hal pembuatan dokumen hukum wajib mendapatkan persetujuan tertulis lebih dahulu dari advokat pada Lembaga Pemberi Layanan Posbakum sebelum diserahkan kepada Penerima Posbakum.', 'Spesifikasi Layanan Sesuai dengan dokumen Kerangka Acua Kerja Terlampir.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 278484);
